 * 5=Brownian, 6=Converge, 7=Diverge, 8=Pedal Point, 9=Hopscotch
 */
function buildPlaybackPattern(values, stagesLength, stageOffset, order) {
	const len = stagesLength;
	const baseIndices = [];
	for (let i = 0; i < len; i++) {
