        nobj("obj-232", "prepend update_gate_scale", 2, 1, [""], [500, 570, 130, 22]),
        nobj("obj-233", "append 0", 2, 1, [""], [500, 600, 55, 22]),
        nobj("obj-234", "prepend update_gate_stretching", 2, 1, [""], [700, 570, 150, 22]),
