    # Fix obj-110 fan-out orders for existing connections (from Phase 1)
    # obj-110 already connects to obj-118[1], obj-122[1], obj-123[1]
    for ll in root["lines"]:
        pl = ll["patchline"]
        if pl["source"] == ["obj-110", 0]:
            dst = pl["destination"]
