def main():
    print("Building Metropolix Stage 2...")
    with open(PATCH_PATH) as f:
        patch = json.load(f)
    patch = transform(patch)
    with open(PATCH_PATH, "w") as f:
        json.dump(patch, f, indent=2)
    print(f"\nWrote {PATCH_PATH}")


if __name__ == "__main__":
    main()

